/**
 * @jest-environment node
 *
 * The AI model never supplies braille. These tests feed adversarial model output (wrong dots,
 * older-code terms, Nemeth, Unicode braille, made-up cells, dot numbers in odd forms, bogus
 * tokens, wrong worksheet answers) through the sanitizer and through the real document builders
 * (with pdfkit and pptxgenjs replaced by recorders), and prove that none of it reaches a document:
 * every drawn cell and every dot phrase in the output is generated by lib/braille, and contracted
 * word answers match liblouis en-ueb-g2.
 */
import oracle from '../fixtures/liblouis-oracle.json';
import { sanitizeGeneratedContent, sanitizeText, type SanitizeIssue } from '@/lib/ai-content-sanitizer';
import { worksheetBraille, gradeForDifficulty, type BrailleGrade } from '@/lib/worksheet-braille';
import { describeCell, describeCells } from '@/lib/braille/prose';
import { INDICATORS, LETTER_CELLS, cellsToUnicode, unicodeToCells, type Cell } from '@/lib/braille/ueb';
import { dotSpecRegExp, findClaims, judgeClaim, parseDotSpec } from '@/lib/braille-validator';
import {
  FACT_TOKENS,
  buildBrailleReference,
  buildPedagogicalPreamble,
  PROMPT_EXAMPLES,
} from '@/lib/ai-braille-reference';

/* ── Recorders for pdfkit and pptxgenjs ─────────────────────────────────── */

interface Drawn {
  texts: string[];
  /** Raised dots of each drawn cell, in drawing order. */
  cells: Cell[];
}
const drawn: Drawn = { texts: [], cells: [] };

jest.mock('pdfkit', () => {
  const RAISED = '#1B2A4A';
  return jest.fn().mockImplementation(() => {
    let color = '';
    let current: number[] | null = null;
    let dotIndex = 0;
    const handlers: Record<string, (() => void)[]> = {};
    // Cells are drawn as a rounded rect followed by six circles in ALL_DOTS order (1..6).
    const doc: Record<string, unknown> = { y: 100, x: 60, page: { height: 792 } };
    const chain = () => doc;
    Object.assign(doc, {
      on: (ev: string, fn: () => void) => ((handlers[ev] ??= []).push(fn), doc),
      end: () => {
        (handlers.data ?? []).forEach((f) => (f as unknown as (b: Buffer) => void)(Buffer.from('pdf')));
        (handlers.end ?? []).forEach((f) => f());
      },
      save: chain,
      restore: chain,
      roundedRect: () => {
        current = [];
        dotIndex = 0;
        drawn.cells.push(current as Cell);
        return doc;
      },
      rect: chain,
      moveTo: chain,
      lineTo: chain,
      strokeColor: chain,
      lineWidth: chain,
      stroke: chain,
      fontSize: chain,
      font: chain,
      moveDown: chain,
      addPage: chain,
      switchToPage: chain,
      bufferedPageRange: () => ({ start: 0, count: 1 }),
      image: chain,
      opacity: chain,
      fillOpacity: chain,
      text: (t: string) => {
        drawn.texts.push(String(t));
        return doc;
      },
      widthOfString: () => 10,
      heightOfString: () => 10,
      circle: () => {
        dotIndex++;
        return doc;
      },
      fillColor: (c: string) => {
        color = c;
        return doc;
      },
      fill: () => {
        if (color === RAISED && current) current.push(dotIndex);
        return doc;
      },
    });
    return doc;
  });
});

jest.mock('pptxgenjs', () =>
  jest.fn().mockImplementation(() => {
    const slide = {
      background: {},
      addText: (t: string | { text: string }[]) => {
        if (typeof t === 'string') drawn.texts.push(t);
        else for (const x of t) drawn.texts.push(x.text);
      },
      addShape: () => undefined,
      addNotes: (t: string) => drawn.texts.push(t),
    };
    return { layout: '', ShapeType: { rect: 'rect' }, addSlide: () => slide, write: async () => Buffer.from('pptx') };
  }),
);

// Imported after the mocks.
import {
  generatePdfBuffer,
  generatePptxBuffer,
  generateQuizPdfBuffer,
  generateWorksheetPdfBuffer,
} from '@/lib/document-builders';

beforeEach(() => {
  drawn.texts = [];
  drawn.cells = [];
});

/* ── Adversarial input ──────────────────────────────────────────────────── */

const B = describeCell(LETTER_CELLS.b);
const NUMERIC = describeCells(INDICATORS.numeric.cells);

/** Sentences no document may contain in any form. */
const POISON = [
  'The letter B is dots 1 4.', // wrong dots (regenerated)
  'Remember: dots 7 and 8 are used for computer braille.', // 8-dot cells
  'In Nemeth Code the digit 1 is dot 2.', // other code
  'EBAE used a different sign here.', // other code
  'The cell ⠃ means but.', // Unicode braille
  'Press dots one and four together.', // dot numbers in words
  'Then add dot-6.', // hyphenated
  'Raise positions 1 and 4.', // positions
  'The zork sign is dots 1 2 3 4 5 6.', // made-up sign (unlabelled claim)
  'Write dots 3 4 5 6 first.', // dot numbers not tied to a sign
  'Use {braille:b} here.', // token that would print a braille character
  'The cell is {dots:zork}.', // unknown sign
  'Count {fact:madeUp}.', // unknown fact
  'The letter b is dots 1 2 7.', // dot 7 in a claim
];

const EBAE_TERMS = [
  ['Use the letter sign before a single letter.', 'grade 1 indicator'],
  ['Put the number sign before digits.', 'numeric indicator'],
  ['The double capital sign marks a whole word.', 'capitalized word indicator'],
] as const;

const GOOD = ['The numeric indicator is {dots:numeric}.', 'The letter b is {letter:b}.'];

function paragraph(): string {
  return [...POISON, ...EBAE_TERMS.map(([s]) => s), ...GOOD].join(' ');
}

function rawWorksheet() {
  return {
    sections: [
      {
        heading: 'Read it',
        type: 'braille-to-print',
        instructions: 'Read each word. ⠁⠃⠉',
        items: [
          // Model tried to write the braille itself (wrong): only `print` is used.
          { prompt: 'What word is dots 1 4, 1, 2 3 4 5?', answer: 'cat', print: 'cat' },
          { prompt: 'Read ⠯', answer: 'and', print: 'and' },
          // No print, braille in the prompt, dots as the answer: dropped.
          { prompt: 'What is ⠃?', answer: 'dots 1 2' },
        ],
      },
      {
        heading: 'Write it',
        type: 'print-to-braille',
        instructions: 'Write each word in braille.',
        items: [
          { prompt: 'Write "the"', answer: 'dots 2 3 4 6', print: 'the' }, // wrong answer: regenerated
          { prompt: 'Write 42', answer: 'dots 3 4 5 6, 1, 1 2', print: '42' },
          { prompt: 'Write B', answer: 'dot 6, then dots 1 2', print: 'B' },
          { prompt: 'Write a made-up word', answer: 'dots 7 8', print: 'zxqv' }, // not writable: dropped
        ],
      },
      {
        heading: 'Which dots',
        type: 'dot-identification',
        instructions: 'Name the dots.',
        items: [{ prompt: 'A cell with dots 1 4 5 6 7', answer: 'dots 1 4 5 6 7', print: 'y' }],
      },
      {
        heading: 'Drill',
        type: 'practice-drill',
        instructions: 'Practice.',
        items: [{ prompt: 'Write this word. In Nemeth it is different.', answer: 'dots 1 2', print: 'but' }],
      },
      {
        heading: 'Facts',
        type: 'fill-in-the-blank',
        instructions: 'Fill in the blank.',
        items: [
          { prompt: 'The letter sign is also called the ___.', answer: 'grade 1 indicator' },
          { prompt: 'The letter c is dots ___.', answer: 'dots 1 4 6' }, // a dot claim as an answer: removed
          { prompt: 'The cell has ___ dots.', answer: 'six' },
        ],
      },
    ],
  };
}

/* ── Checks every document output must pass ─────────────────────────────── */

const BAD_TEXT: [string, RegExp][] = [
  ['Unicode braille', /[⠀-⣿]/u],
  ['another braille code', /nemeth|\bebae\b|computer braille/i],
  ['an older-code term', /letter sign|number sign|double capital/i],
  ['8-dot cells', /\bdots?\b[^.\n]{0,20}\b[78]\b/i],
  ['dot numbers in words or odd forms', /\bdots? (?:one|two|three|four|five|six)\b|dot-[0-9]|positions? [0-9]/i],
  ['an unrendered or rejected token', /\{\w+:[^}]*\}/],
  ['the poison', /zork|madeUp|dots 1 4\.|dots 1 2 3 4 5 6/],
];

function expectCleanText(texts: string[]) {
  const all = texts.join('\n');
  for (const [what, re] of BAD_TEXT) expect({ what, found: all.match(re)?.[0] ?? null }).toEqual({ what, found: null });
  // Every dot phrase left is in the canonical generated form, and every claim it is part of is true.
  for (const t of texts) {
    const re = dotSpecRegExp();
    let m: RegExpExecArray | null;
    while ((m = re.exec(t)) !== null) {
      if (m[0].length === 0) {
        re.lastIndex++;
        continue;
      }
      const cells = parseDotSpec(m[0]);
      expect(cells.length).toBeGreaterThan(0);
      expect(t).toContain(describeCells(cells));
    }
    for (const c of findClaims(t)) expect(judgeClaim(c.target.accepted, parseDotSpec(c.spec))).toBe('ok');
  }
}

/** Every drawn cell row must be the generated braille of one of the item prints. */
function expectCellsFromPrints(prints: string[], grade: BrailleGrade) {
  const allowed = prints.map((p) => worksheetBraille(p, grade)!).filter(Boolean);
  const drawnKeys = drawn.cells.map((c) => [...c].sort().join(''));
  const allowedKeys = new Set(allowed.flat().map((c) => [...c].sort().join('')));
  for (const k of drawnKeys) if (k !== '') expect(allowedKeys.has(k) ? k : `not generated: ${k}`).toBe(k);
  return allowed;
}

/* ── Tests ──────────────────────────────────────────────────────────────── */

describe('sanitizeText: the model cannot put braille into a sentence', () => {
  test.each(POISON)('%s → removed or regenerated', (s) => {
    const issues: SanitizeIssue[] = [];
    const out = sanitizeText(s, 'uncontracted', issues);
    expect(issues.length).toBeGreaterThan(0);
    expectCleanText([out]);
  });

  test('a wrong claim about a named letter is regenerated from lib/braille', () => {
    expect(sanitizeText('The letter B is dots 1 4.', 'uncontracted')).toBe(`The letter B is ${B}.`);
  });

  test.each(EBAE_TERMS)('%s → UEB name', (s, ueb) => {
    expect(sanitizeText(s, 'uncontracted')).toContain(ueb);
  });

  test('"capital letter indicator" (the UEB name) is left alone', () => {
    expect(sanitizeText('Use the capital letter indicator.', 'uncontracted')).toBe('Use the capital letter indicator.');
  });

  test('"number sign" meaning the # symbol is left alone', () => {
    expect(sanitizeText('The number sign (#) is used for hashtags.', 'uncontracted')).toContain('number sign');
  });

  test('allowed tokens are rendered from lib/braille', () => {
    expect(sanitizeText(GOOD.join(' '), 'uncontracted')).toBe(
      `The numeric indicator is ${NUMERIC}. The letter b is ${B}.`,
    );
  });

  test('contraction tokens only in contracted material', () => {
    expect(sanitizeText('The word and is {dots:contraction:and}.', 'uncontracted')).toBe('');
    expect(sanitizeText('The word and is {dots:contraction:and}.', 'contracted')).toBe(
      `The word and is ${describeCells(unicodeToCells('⠯'))}.`,
    );
  });

  test('uebdots (uncontracted cell by cell) is refused in contracted material', () => {
    expect(sanitizeText('cat is {uebdots:cat}.', 'contracted')).toBe('');
  });

  test('stored drafts keep their tokens, and sanitizing again changes nothing (idempotent)', () => {
    for (const grade of ['uncontracted', 'contracted'] as const) {
      const once = sanitizeGeneratedContent('worksheet', rawWorksheet(), grade).content;
      const twice = sanitizeGeneratedContent('worksheet', once).content;
      expect(twice).toEqual(once);
      const pdf = { sections: [{ heading: 'H', content: paragraph() }] };
      const p1 = sanitizeGeneratedContent('pdf', pdf, grade).content;
      expect(JSON.stringify(p1)).toContain('{dots:numeric}');
      expect(sanitizeGeneratedContent('pdf', p1).content).toEqual(p1);
    }
  });
});

describe('worksheets: braille items are rebuilt from their print', () => {
  test.each(['uncontracted', 'contracted'] as const)('%s: prompts and answers are generated', (grade) => {
    const { content, issues } = sanitizeGeneratedContent('worksheet', rawWorksheet(), grade);
    const sections = content.sections as {
      type: string;
      items: { prompt: string; answer: string; print?: string }[];
    }[];
    const items = sections.flatMap((s) => s.items.map((i) => ({ ...i, type: s.type })));
    for (const it of items.filter((i) => i.print)) {
      const cells = worksheetBraille(it.print!, grade)!;
      expect(cells).not.toBeNull();
      if (it.type !== 'braille-to-print') expect(it.answer).toBe(describeCells(cells));
    }
    // The unprinted item, the unwritable word and the dot-claim answer are gone, with reasons.
    expect(items.map((i) => i.prompt).join(' ')).not.toMatch(/What is|made-up|The letter c is dots/);
    // ("zxqv" can be spelled letter by letter in uncontracted braille, so only contracted drops it.)
    expect(issues.filter((i) => i.kind === 'item-removed').length).toBe(grade === 'contracted' ? 3 : 2);
    expectCleanText(items.flatMap((i) => [i.prompt, i.answer]));
  });

  test('the grade comes from the admin difficulty: beginner is uncontracted, the others contracted', () => {
    expect(gradeForDifficulty('beginner')).toBe('uncontracted');
    expect(gradeForDifficulty('intermediate')).toBe('contracted');
    expect(gradeForDifficulty('advanced')).toBe('contracted');
  });
});

describe('the built documents contain only generated braille', () => {
  const translations = oracle.translations as Record<string, string>;
  const PRINTS = ['cat', 'and', 'the', '42', 'B', 'y', 'but', 'zxqv'];

  test.each(['uncontracted', 'contracted'] as const)('%s worksheet PDF', async (grade) => {
    // The raw model output goes straight to the builder: it must sanitize it itself.
    await generateWorksheetPdfBuffer({ ...rawWorksheet(), brailleGrade: grade } as never, 'Test');
    expectCleanText(drawn.texts);
    const allowed = expectCellsFromPrints(PRINTS, grade);
    expect(drawn.cells.filter((c) => c.length > 0).length).toBeGreaterThan(0);
    // Each print's cells appear in the answer key, in order, exactly as generated.
    const seq = drawn.cells.map((c) => [...c].sort().join('')).join('|');
    for (const cells of allowed) expect(seq).toContain(cells.map((c) => [...c].sort().join('')).join('|'));
  });

  test('contracted word answers are drawn in the form liblouis en-ueb-g2 gives', async () => {
    for (const p of ['and', 'the', 'but', 'B', 'y', '42', 'Knowledge', 'people', 'child']) {
      const cells = worksheetBraille(p, 'contracted');
      expect({ p, braille: cells && cellsToUnicode(cells) }).toEqual({ p, braille: translations[`g2\t${p}`] });
    }
    for (const p of ['and', 'the', 'cat', 'B']) {
      const cells = worksheetBraille(p, 'uncontracted');
      expect({ p, braille: cells && cellsToUnicode(cells) }).toEqual({ p, braille: translations[`g1\t${p}`] });
    }
  });

  test.each(['uncontracted', 'contracted'] as const)('%s handout, study guide, quiz and slides', async (grade) => {
    const text = paragraph();
    await generatePdfBuffer(
      { sections: [{ heading: 'Dots', content: text, bullets: POISON }], brailleGrade: grade } as never,
      'H',
      false,
    );
    await generatePdfBuffer(
      {
        title: 'Guide',
        objectives: POISON,
        sections: [
          {
            heading: 'Terms',
            content: text,
            keyTerms: ['b', 'B', 'numeric indicator', '⠃', 'dots 1 4'],
            practiceQuestions: POISON,
          },
        ],
        brailleGrade: grade,
      } as never,
      'G',
      true,
    );
    await generateQuizPdfBuffer(
      {
        questions: [
          {
            type: 'short-answer',
            question: 'What is the letter b?',
            answer: 'dots 1 4',
            explanation: 'The letter b is dots 1 4.',
          },
          {
            type: 'multiple-choice',
            question: 'Which is b?',
            options: ['dots 1 2', '⠃', 'dot 7', 'dots one two'],
            answer: 'A',
            explanation: '',
          },
          {
            type: 'true-false',
            question: 'The numeric indicator is {dots:numeric}.',
            options: ['True', 'False'],
            answer: 'True',
            explanation: 'In Nemeth it is different.',
          },
        ],
        brailleGrade: grade,
      } as never,
      'Q',
    );
    await generatePptxBuffer({
      slides: [{ title: 'Dots', bullets: POISON, speakerNotes: text }],
      brailleGrade: grade,
    } as never);
    expectCleanText(drawn.texts);
    // The key term "b" is drawn as generated (with the grade 1 indicator in contracted braille).
    expectCellsFromPrints(['b', 'B'], grade);
    const all = drawn.texts.join('\n');
    expect(all).toContain(`The numeric indicator is ${NUMERIC}.`);
    expect(all).not.toContain('What is the letter b?'); // its answer was a dot claim the site could not keep
  });
});

describe('what the model is told', () => {
  test.each(['beginner', 'intermediate', 'advanced'] as const)(
    '%s: the prompt contains no dot numbers and no braille',
    (level) => {
      const prompt = buildPedagogicalPreamble(level) + buildBrailleReference(level) + JSON.stringify(PROMPT_EXAMPLES);
      expect(prompt).not.toMatch(/[⠀-⣿]/u);
      expect(prompt).not.toMatch(/\bdots?\s*[1-8]/i);
      expect(prompt).toMatch(/NEVER write dot numbers/);
    },
  );

  test('every token the reference shows renders (so the model is not taught a token that fails)', () => {
    const ref = buildBrailleReference('advanced');
    const ids = [...ref.matchAll(/^ {2}([a-z][a-zA-Z0-9-]*): /gm)].map((m) => m[1]);
    expect(ids.length).toBeGreaterThan(30);
    for (const id of ids.filter((x) => !(x in FACT_TOKENS)))
      expect(sanitizeText(`Sign {dots:${id}} and {name:${id}}.`, 'contracted')).not.toBe('');
    for (const f of Object.keys(FACT_TOKENS)) expect(sanitizeText(`Fact {fact:${f}}.`, 'contracted')).not.toBe('');
  });
});
